static String pobierzDane(int proba) {
    if (proba < 3) {
        throw new RuntimeException("timeout");
    }
    return "dane OK";
}

public static void main(String[] args) {
    int maxProb = 5;
    boolean sukces = false;
    for (int proba = 1; proba <= maxProb; proba++) {
        try {
            String wynik = pobierzDane(proba);
            System.out.println("Sukces przy probie " + proba + ": " + wynik);
            sukces = true;
            break;
        } catch (RuntimeException e) {
            System.out.println("Proba " + proba + " nieudana: " + e.getMessage());
        }
    }
    if (!sukces) {
        System.out.println("Poddano sie po " + maxProb + " probach");
    }
}

