static void wykonajOperacje() {
    RuntimeException glowny = null;
    try {
        throw new RuntimeException("blad operacji");
    } catch (RuntimeException e) {
        glowny = e;
    } finally {
        try {
            zamknijZasob("plik.txt", true);
        } catch (RuntimeException zamkniecie) {
            if (glowny != null) {
                glowny.addSuppressed(zamkniecie);
            }
        }
    }
    if (glowny != null) {
        throw glowny;
    }
}

public static void main(String[] args) {
    try {
        wykonajOperacje();
    } catch (RuntimeException e) {
        System.out.println("Glowny: " + e.getMessage());
        for (Throwable suppressed : e.getSuppressed()) {
            System.out.println("Suppressed: " + suppressed.getMessage());
        }
    }
}

