static void przelej(java.util.Map<String, Integer> konta, String zKogo, String doKogo, int kwota) {
    int noweSaldo = konta.get(zKogo) - kwota;
    konta.put(zKogo, noweSaldo);
    if (noweSaldo < 0) {
        konta.put(zKogo, konta.get(zKogo) + kwota); // rollback
        throw new IllegalStateException("Niewystarczajace srodki na koncie " + zKogo);
    }
    konta.put(doKogo, konta.get(doKogo) + kwota);
}

public static void main(String[] args) {
    java.util.Map<String, Integer> konta = new java.util.HashMap<>();
    konta.put("A", 100);
    konta.put("B", 50);

    przelej(konta, "A", "B", 30);
    System.out.println("Po udanym przelewie: " + konta);

    try {
        przelej(konta, "A", "B", 1000);
    } catch (IllegalStateException e) {
        System.out.println("Blad: " + e.getMessage());
    }
    System.out.println("Po nieudanym przelewie (bez zmian): " + konta);
}

enum StanZamowienia { NOWE, OPLACONE, WYSLANE, DOSTARCZONE }

static class NiedozwolonePrzejscieException extends RuntimeException {
    public NiedozwolonePrzejscieException(String message) { super(message); }
}

static void zmienStan(StanZamowienia obecny, StanZamowienia docelowy) {
    if (docelowy.ordinal() != obecny.ordinal() + 1) {
        throw new NiedozwolonePrzejscieException("Nie mozna przejsc z " + obecny + " do " + docelowy);
    }
    System.out.println("Przejscie OK: " + obecny + " -> " + docelowy);
}

public static void main(String[] args) {
    try {
        zmienStan(StanZamowienia.NOWE, StanZamowienia.OPLACONE);
        zmienStan(StanZamowienia.NOWE, StanZamowienia.WYSLANE);
    } catch (NiedozwolonePrzejscieException e) {
        System.out.println("Blad: " + e.getMessage());
    }
}

record Podsumowanie(int sukcesy, int porazki, java.util.List<String> bledy) {}

static void przetworzZamowienie(int kwota) {
    if (kwota <= 0) {
        throw new IllegalArgumentException("Niepoprawna kwota: " + kwota);
    }
}

static Podsumowanie przetworzWszystkie(int[] kwoty) {
    int sukcesy = 0, porazki = 0;
    java.util.List<String> bledy = new java.util.ArrayList<>();
    for (int kwota : kwoty) {
        try {
            przetworzZamowienie(kwota);
            sukcesy++;
        } catch (IllegalArgumentException e) {
            porazki++;
            bledy.add(e.getMessage());
        }
    }
    return new Podsumowanie(sukcesy, porazki, bledy);
}

public static void main(String[] args) {
    int[] kwoty = {100, -5, 0, 200, 50, -1, 300, 0, 75, 400};
    Podsumowanie wynik = przetworzWszystkie(kwoty);
    System.out.println("Sukcesy: " + wynik.sukcesy() + ", Porazki: " + wynik.porazki());
    System.out.println("Bledy: " + wynik.bledy());
}

static class RejestracjaException extends Exception {
    private final java.util.List<String> bledy;
    public RejestracjaException(String message, java.util.List<String> bledy) {
        super(message);
        this.bledy = bledy;
    }
    public java.util.List<String> getBledy() { return bledy; }
}

static void zarejestruj(String imie, String email, String wiekStr) throws RejestracjaException {
    java.util.List<String> bledy = new java.util.ArrayList<>();

    if (imie == null || imie.isEmpty()) {
        bledy.add("Imie jest puste");
    }
    if (email == null || !email.contains("@")) {
        bledy.add("Email jest niepoprawny");
    }
    try {
        int wiek = Integer.parseInt(wiekStr);
        if (wiek < 0 || wiek > 150) {
            bledy.add("Wiek poza zakresem: " + wiek);
        }
    } catch (NumberFormatException e) {
        bledy.add("Wiek nie jest liczba: " + wiekStr);
    }

    if (!bledy.isEmpty()) {
        throw new RejestracjaException("Rejestracja nieudana", bledy);
    }
    System.out.println("Rejestracja OK: " + imie);
}

public static void main(String[] args) {
    try {
        zarejestruj("Anna", "anna@example.com", "25");
    } catch (RejestracjaException e) {
        System.out.println(e.getBledy());
    }
    try {
        zarejestruj("", "zlyemail", "abc");
    } catch (RejestracjaException e) {
        System.out.println(e.getBledy());
    }
}
